import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"ColHead","description":"","frontmatter":{},"headers":[],"relativePath":"components/col-head.md","filePath":"components/col-head.md"}'),n={name:"components/col-head.md"};function r(c,e,s,h,i,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="colhead" tabindex="-1">ColHead <a class="header-anchor" href="#colhead" aria-label="Permalink to &quot;ColHead&quot;">​</a></h1><p>ColHead is the content of a table&#39;s column header: the column&#39;s name, which sorts the table when pressed.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it in a <code>th</code> of a <a href="./table">Table</a>. A column that cannot be sorted takes no <code>onsort</code>. A press asks for the next direction: the column&#39;s <code>first</code> direction when the table is not sorted by it yet (a column of dates starts with <code>desc</code>), then the other one. The application sorts the rows and sets <code>aria-sort</code> on the <code>th</code>. A column that can be sorted has a column menu with the two directions and, for the sort key, clearing the sort (<code>onsort(null)</code>); <code>menu</code> adds the application&#39;s own <a href="./menu-item">MenuItems</a>. Two columns merged into one on a narrow screen pass <code>sorts</code> and <code>onsortKey</code>; their menu holds <code>menu</code> only.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>dir</code></td><td></td><td>The direction when the table is sorted by this column</td></tr><tr><td><code>onsort</code></td><td></td><td>Called with the next direction</td></tr><tr><td><code>first</code></td><td><code>asc</code></td><td>The first direction of the column</td></tr><tr><td><code>sorts</code></td><td></td><td>The names of merged columns (below)</td></tr><tr><td><code>onsortKey</code></td><td></td><td>Called with a merged column&#39;s id and direction</td></tr><tr><td><code>menu</code></td><td></td><td>Items of the column menu; receives the close function</td></tr><tr><td><code>children</code></td><td></td><td>The name</td></tr></tbody></table><p>Each item of <code>sorts</code> has <code>id</code> and <code>label</code>, and optionally <code>dir</code>, <code>first</code>, and <code>sortable: false</code> for a name that cannot be pressed.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The name has the height of a small button and no padding at the sides, so that it lines up with the text of the column; it is trimmed to its ink and underlines on hover. The sort key shows a blue chevron after the name, down for descending and up for ascending, and its name is in the text color. The column menu is a ghost icon button (a chevron) at the right end of the header, which opens a <a href="./dropdown">Dropdown</a> menu; the current direction has a check mark. The names of merged columns stack, touching. The words of the menu come from the messages <code>actions</code>, <code>sortAscending</code>, <code>sortDescending</code> and <code>clearSort</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/col-head/" title="ColHead" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/col-head/" target="_blank" rel="noopener">ColHead</a></figcaption></figure>',11)])])}const p=t(n,[["render",r]]);export{u as __pageData,p as default};
